# SurrealDB schema definition with performance indexes
SURREAL_JOURNEY_SCHEMA = """
-- Journey nodes
DEFINE TABLE journey SCHEMAFULL;
DEFINE FIELD id ON TABLE journey TYPE string;
DEFINE FIELD skill_domain ON TABLE journey TYPE string;
DEFINE FIELD intent ON TABLE journey TYPE string;
DEFINE FIELD final_phi ON TABLE journey TYPE float DEFAULT 0.0;
DEFINE FIELD final_coherence ON TABLE journey TYPE float DEFAULT 0.0;
DEFINE FIELD final_efficiency ON TABLE journey TYPE float DEFAULT 0.0;
DEFINE FIELD success ON TABLE journey TYPE bool DEFAULT false;
DEFINE FIELD total_tokens ON TABLE journey TYPE int DEFAULT 0;
DEFINE FIELD num_steps ON TABLE journey TYPE int DEFAULT 0;
DEFINE FIELD start_time ON TABLE journey TYPE float DEFAULT 0.0;
DEFINE FIELD end_time ON TABLE journey TYPE float DEFAULT 0.0;
DEFINE FIELD duration_seconds ON TABLE journey TYPE float
    DEFAULT (end_time - start_time);
DEFINE FIELD created_at ON TABLE journey TYPE datetime DEFAULT time::now();
DEFINE FIELD metadata ON TABLE journey TYPE object DEFAULT {};

-- Journey Step nodes
DEFINE TABLE journey_step SCHEMAFULL;
DEFINE FIELD id ON TABLE journey_step TYPE string;
DEFINE FIELD journey_id ON TABLE journey_step TYPE string;
DEFINE FIELD step_number ON TABLE journey_step TYPE int;
DEFINE FIELD task_description ON TABLE journey_step TYPE string;
DEFINE FIELD output ON TABLE journey_step TYPE string;
DEFINE FIELD success ON TABLE journey_step TYPE bool DEFAULT false;
DEFINE FIELD phi_score ON TABLE journey_step TYPE float DEFAULT 0.0;
DEFINE FIELD coherence ON TABLE journey_step TYPE float DEFAULT 0.0;
DEFINE FIELD efficiency ON TABLE journey_step TYPE float DEFAULT 0.0;
DEFINE FIELD duration_seconds ON TABLE journey_step TYPE float DEFAULT 0.0;
DEFINE FIELD timestamp ON TABLE journey_step TYPE float DEFAULT 0.0;
DEFINE FIELD trajectory_12d ON TABLE journey_step TYPE array;
DEFINE FIELD trajectory_12d[*] ON TABLE journey_step TYPE float;
DEFINE FIELD metadata ON TABLE journey_step TYPE object DEFAULT {};

-- Skill nodes
DEFINE TABLE skill SCHEMAFULL;
DEFINE FIELD id ON TABLE skill TYPE string;
DEFINE FIELD name ON TABLE skill TYPE string;
DEFINE FIELD description ON TABLE skill TYPE string;
DEFINE FIELD complexity_levels ON TABLE skill TYPE array DEFAULT [];
DEFINE FIELD usage_count ON TABLE skill TYPE int DEFAULT 0;
DEFINE FIELD avg_phi ON TABLE skill TYPE float DEFAULT 0.0;
DEFINE FIELD avg_coherence ON TABLE skill TYPE float DEFAULT 0.0;
DEFINE FIELD created_at ON TABLE skill TYPE datetime DEFAULT time::now();

-- Graph relationships
DEFINE TABLE has_step TYPE RELATION IN journey OUT journey_step;
DEFINE TABLE journey_uses_skill TYPE RELATION IN journey OUT skill;
DEFINE TABLE step_uses_skill TYPE RELATION IN journey_step OUT skill;
DEFINE TABLE next_step TYPE RELATION IN journey_step OUT journey_step;

-- OPTIMIZED: Indexes for high-performance batch operations
-- Journey indexes
DEFINE INDEX journey_skill_idx ON journey FIELDS skill_domain;
DEFINE INDEX journey_success_idx ON journey FIELDS success;
DEFINE INDEX INDEX journey_phi_idx ON journey FIELDS final_phi;
DEFINE INDEX journey_coherence_idx ON journey FIELDS final_coherence;
DEFINE INDEX journey_created_idx ON journey FIELDS created_at;
DEFINE INDEX journey_tokens_idx ON journey FIELDS total_tokens;

-- Journey step indexes (critical for batch queries)
DEFINE INDEX journey_step_journey_idx ON journey_step FIELDS journey_id;
DEFINE INDEX journey_step_number_idx ON journey_step FIELDS step_number;
DEFINE INDEX journey_step_success_idx ON journey_step FIELDS success;
DEFINE INDEX journey_step_phi_idx ON journey_step FIELDS phi_score;

-- Skill indexes
DEFINE INDEX skill_name_idx ON skill FIELDS name UNIQUE;
DEFINE INDEX skill_usage_idx ON skill FIELDS usage_count;

-- NEW: Composite indexes for common query patterns
DEFINE INDEX journey_skill_success_idx ON journey FIELDS skill_domain, success;
DEFINE INDEX journey_skill_phi_idx ON journey FIELDS skill_domain, final_phi;
DEFINE INDEX journey_step_journey_number_idx ON journey_step FIELDS journey_id, step_number;
"""

