"""Fast serialization utilities for internal hot paths.

Uses MessagePack for binary serialization (3x faster decode, 30-40% smaller)
while maintaining JSON compatibility for external APIs and human-readable storage.
"""

from __future__ import annotations

import json
import logging
from typing import Any

import msgpack


logger = logging.getLogger(__name__)


def pack(data: Any) -> bytes:
    """Serialize data to MessagePack binary format."""
    return msgpack.packb(data, use_bin_type=True)


def unpack(data: bytes) -> Any:
    """Deserialize MessagePack binary data."""
    return msgpack.unpackb(data, raw=False)


def pack_line(record: dict[str, Any]) -> bytes:
    """Serialize a record as a msgpack-encoded line (for binary JSONL replacement)."""
    return msgpack.packb(record, use_bin_type=True)


def unpack_line(data: bytes) -> dict[str, Any]:
    """Deserialize a msgpack-encoded record."""
    return msgpack.unpackb(data, raw=False)


def to_json(data: Any, indent: int | None = None) -> str:
    """Serialize to JSON string (for external APIs and human-readable output)."""
    return json.dumps(data, indent=indent, default=str)


def from_json(data: str) -> Any:
    """Deserialize from JSON string."""
    return json.loads(data)

