@app.post("/compound/execute/stream")
async def compound_execute_stream(request: CompoundExecuteRequest):
    """Stream compound skill execution via Server-Sent Events.

    Each pipeline step emits an SSE event as it completes, enabling
    real-time progress tracking without polling.
    """
    import asyncio

    from sse_starlette.sse import EventSourceResponse

    from cohezion.compound.executor import get_executor

    async def event_generator():
        executor = get_executor()
        try:
            yield {"event": "started", "data": json.dumps({"skill_name": request.skill_name})}

            result = await executor.execute_skill(
                request.skill_name,
                request.input_text,
                model=request.model,
            )

            for step in result.steps:
                yield {
                    "event": "step",
                    "data": json.dumps({
                        "step_index": step["step_index"],
                        "operation": step["operation"],
                        "description": step["description"],
                        "tokens_used": step["tokens_used"],
                        "duration_ms": step["duration_ms"],
                    }),
                }
                await asyncio.sleep(0)  # Yield control to send event

            yield {
                "event": "completed",
                "data": json.dumps({
                    "skill_name": result.skill_name,
                    "total_tokens": result.total_tokens,
                    "total_duration_ms": result.total_duration_ms,
                    "final_output": result.final_output[:500],
                }),
            }
        except KeyError:
            yield {"event": "error", "data": json.dumps({"detail": f"Skill not found: {request.skill_name}"})}
        except Exception as exc:
            logger.exception("Compound SSE execution failed: %s", request.skill_name)
            yield {"event": "error", "data": json.dumps({"detail": str(exc)[:200]})}

    return EventSourceResponse(event_generator())


