"""Tests for Physics Service - 12D physics state operations."""

from __future__ import annotations

from unittest.mock import AsyncMock, MagicMock

import numpy as np
import pytest

from cohezion.services.physics_service import (
    PhysicsAnalysis,
    PhysicsConfig,
    PhysicsService,
)


@pytest.fixture
def mock_universe_repo():
    return AsyncMock()


@pytest.fixture
def service(mock_universe_repo):
    return PhysicsService(universe_repo=mock_universe_repo)


@pytest.fixture
def config():
    return PhysicsConfig()


class TestPhysicsConfig:
    def test_defaults(self):
        cfg = PhysicsConfig()
        assert cfg.similarity_threshold == 0.7
        assert cfg.stability_threshold == 0.5
        assert cfg.coherence_threshold == 0.6
        assert cfg.novelty_decay_rate == 0.95

    def test_custom_values(self):
        cfg = PhysicsConfig(similarity_threshold=0.9, coherence_threshold=0.8)
        assert cfg.similarity_threshold == 0.9
        assert cfg.coherence_threshold == 0.8


class TestComputePhysicsState:
    @pytest.mark.asyncio
    async def test_compute_from_content(self, service):
        state = await service.compute_physics_state("Hello world test content")
        assert 0 <= state.x <= 1
        assert 0 <= state.y <= 1
        assert 0 <= state.z <= 1
        assert 0 <= state.complexity <= 1
        assert -1 <= state.sentiment <= 1

    @pytest.mark.asyncio
    async def test_compute_with_embedding(self, service):
        embedding = [0.5, -0.3, 0.8] + [0.0] * 29
        state = await service.compute_physics_state("content", embedding=embedding)
        # With embedding, spatial position comes from embedding
        assert state.x == pytest.approx((0.5 + 1) / 2)
        assert state.y == pytest.approx((-0.3 + 1) / 2)

    @pytest.mark.asyncio
    async def test_compute_with_metadata(self, service):
        state = await service.compute_physics_state(
            "content",
            metadata={"timestamp": 1e12},
        )
        assert state.time == pytest.approx(1e12 / 1e9)

    @pytest.mark.asyncio
    async def test_compute_empty_content(self, service):
        state = await service.compute_physics_state("")
        assert state.complexity == 0.0

    @pytest.mark.asyncio
    async def test_compute_sentiment_positive(self, service):
        state = await service.compute_physics_state("This is great and excellent")
        assert state.sentiment > 0

    @pytest.mark.asyncio
    async def test_compute_sentiment_negative(self, service):
        state = await service.compute_physics_state("This is bad with error and fail")
        assert state.sentiment < 0

    @pytest.mark.asyncio
    async def test_compute_novelty_with_rare_words(self, service):
        state = await service.compute_physics_state(
            "quantum fractal symmetry entropy coherence"
        )
        assert state.novelty > 0

    @pytest.mark.asyncio
    async def test_compute_factuality(self, service):
        state = await service.compute_physics_state(
            "data analysis result measurement evidence"
        )
        assert state.factuality == 1.0  # 5/5 = capped at 1.0


class TestAnalyzePhysicsState:
    @pytest.mark.asyncio
    async def test_analyze_returns_analysis(self, service):
        from cohezion.core.persistence.repositories.universe_repository import (
            PhysicsState,
        )

        state = PhysicsState(
            stability=0.8, coherence=0.7, connectivity=0.6, novelty=0.5
        )
        analysis = await service.analyze_physics_state(state)
        assert isinstance(analysis, PhysicsAnalysis)
        assert analysis.overall_health > 0

    @pytest.mark.asyncio
    async def test_analyze_low_stability_recommends(self, service):
        from cohezion.core.persistence.repositories.universe_repository import (
            PhysicsState,
        )

        state = PhysicsState(stability=0.3, coherence=0.9, connectivity=0.9, novelty=0.9)
        analysis = await service.analyze_physics_state(state)
        assert any("stabiliz" in r.lower() for r in analysis.recommendations)

    @pytest.mark.asyncio
    async def test_analyze_healthy_state(self, service):
        from cohezion.core.persistence.repositories.universe_repository import (
            PhysicsState,
        )

        state = PhysicsState(
            stability=0.9, coherence=0.9, connectivity=0.9, novelty=0.9
        )
        analysis = await service.analyze_physics_state(state)
        assert any("healthy" in r.lower() for r in analysis.recommendations)


class TestCompareStates:
    @pytest.mark.asyncio
    async def test_identical_states_similarity_one(self, service):
        from cohezion.core.persistence.repositories.universe_repository import (
            PhysicsState,
        )

        state = PhysicsState(x=1, y=0, z=0, mass=1, stability=1, coherence=1)
        sim = await service.compare_states(state, state)
        assert sim == pytest.approx(1.0)

    @pytest.mark.asyncio
    async def test_zero_vector_returns_zero(self, service):
        from cohezion.core.persistence.repositories.universe_repository import (
            PhysicsState,
        )

        state_a = PhysicsState()  # All zeros
        state_b = PhysicsState(x=1, y=1)
        sim = await service.compare_states(state_a, state_b)
        assert sim == 0.0


class TestFindSimilarStates:
    @pytest.mark.asyncio
    async def test_find_similar_returns_list(self, service, mock_universe_repo):
        from cohezion.core.persistence.repositories.universe_repository import (
            PhysicsState,
            UniverseNode,
        )

        mock_node = MagicMock(spec=UniverseNode)
        mock_node.physics_state = PhysicsState(x=1, y=0, stability=0.8, coherence=0.9)
        mock_universe_repo.get_all.return_value = [mock_node]

        state = PhysicsState(x=1, y=0, stability=0.8, coherence=0.9)
        results = await service.find_similar_states(state, limit=5)
        assert isinstance(results, list)

    @pytest.mark.asyncio
    async def test_find_similar_empty_repo(self, service, mock_universe_repo):
        from cohezion.core.persistence.repositories.universe_repository import (
            PhysicsState,
        )

        mock_universe_repo.get_all.return_value = []
        results = await service.find_similar_states(PhysicsState(), limit=5)
        assert results == []


class TestUpdatePhysicsState:
    @pytest.mark.asyncio
    async def test_update_delegates_to_repo(self, service, mock_universe_repo):
        mock_universe_repo.update.return_value = True
        result = await service.update_physics_state("node-1", {"stability": 0.9})
        assert result is True
        mock_universe_repo.update.assert_called_once()

    @pytest.mark.asyncio
    async def test_update_handles_error(self, service, mock_universe_repo):
        mock_universe_repo.update.side_effect = Exception("DB error")
        result = await service.update_physics_state("node-1", {"stability": 0.9})
        assert result is False

"""Tests for Knowledge Service - knowledge graph operations."""

from __future__ import annotations

from unittest.mock import AsyncMock, MagicMock

import pytest

from cohezion.services.knowledge_service import (
    KnowledgeEdge,
    KnowledgeNode,
    KnowledgeQuery,
    KnowledgeService,
)


@pytest.fixture
def mock_universe_repo():
    return AsyncMock()


@pytest.fixture
def mock_skill_repo():
    return AsyncMock()


@pytest.fixture
def service(mock_universe_repo, mock_skill_repo):
    return KnowledgeService(
        universe_repo=mock_universe_repo,
        skill_repo=mock_skill_repo,
    )


class TestKnowledgeNode:
    def test_auto_generates_id(self):
        node = KnowledgeNode(concept="test")
        assert node.id  # UUID generated
        assert len(node.id) == 36  # UUID format

    def test_auto_generates_created_at(self):
        node = KnowledgeNode(concept="test")
        assert node.created_at  # ISO timestamp

    def test_preserves_provided_id(self):
        node = KnowledgeNode(id="custom-id", concept="test")
        assert node.id == "custom-id"

    def test_unique_ids(self):
        n1 = KnowledgeNode(concept="a")
        n2 = KnowledgeNode(concept="b")
        assert n1.id != n2.id

    def test_defaults(self):
        node = KnowledgeNode()
        assert node.concept == ""
        assert node.node_type == "concept"
        assert node.metadata == {}
        assert node.embedding is None


class TestKnowledgeEdge:
    def test_auto_generates_id(self):
        edge = KnowledgeEdge(from_node="a", to_node="b")
        assert edge.id
        assert len(edge.id) == 36

    def test_defaults(self):
        edge = KnowledgeEdge()
        assert edge.edge_type == "related"
        assert edge.weight == 1.0

    def test_auto_generates_created_at(self):
        edge = KnowledgeEdge()
        assert edge.created_at


class TestKnowledgeQuery:
    def test_creation(self):
        q = KnowledgeQuery(
            matched_nodes=[KnowledgeNode(concept="test")],
            matched_edges=[],
            confidence=0.8,
        )
        assert len(q.matched_nodes) == 1
        assert q.confidence == 0.8
        assert q.path == []


class TestAddNode:
    @pytest.mark.asyncio
    async def test_add_node_delegates_to_repo(self, service, mock_universe_repo):
        mock_universe_repo.create.return_value = "node-123"
        node = KnowledgeNode(concept="Machine learning")
        result = await service.add_node(node)
        assert result == "node-123"
        mock_universe_repo.create.assert_called_once()

    @pytest.mark.asyncio
    async def test_add_node_sets_kg_prefix(self, service, mock_universe_repo):
        mock_universe_repo.create.return_value = "id"
        node = KnowledgeNode(concept="test", node_type="skill")
        await service.add_node(node)
        created_node = mock_universe_repo.create.call_args[0][0]
        assert created_node.node_type == "kg_skill"

    @pytest.mark.asyncio
    async def test_add_node_propagates_error(self, service, mock_universe_repo):
        mock_universe_repo.create.side_effect = Exception("DB error")
        with pytest.raises(Exception, match="DB error"):
            await service.add_node(KnowledgeNode(concept="test"))


class TestAddEdge:
    @pytest.mark.asyncio
    async def test_add_edge_delegates_to_repo(self, service, mock_universe_repo):
        mock_universe_repo.create_relationship.return_value = "edge-123"
        edge = KnowledgeEdge(from_node="a", to_node="b", edge_type="depends_on")
        result = await service.add_edge(edge)
        assert result == "edge-123"

    @pytest.mark.asyncio
    async def test_add_edge_falls_back_to_edge_id(self, service, mock_universe_repo):
        mock_universe_repo.create_relationship.return_value = None
        edge = KnowledgeEdge(id="fallback-id", from_node="a", to_node="b")
        result = await service.add_edge(edge)
        assert result == "fallback-id"


class TestQueryConcept:
    @pytest.mark.asyncio
    async def test_query_returns_knowledge_query(self, service, mock_universe_repo):
        mock_universe_repo.query_similar.return_value = []
        result = await service.query_concept("machine learning")
        assert isinstance(result, KnowledgeQuery)
        assert result.confidence == 0.0

    @pytest.mark.asyncio
    async def test_query_handles_error(self, service, mock_universe_repo):
        mock_universe_repo.query_similar.side_effect = Exception("Query failed")
        result = await service.query_concept("test")
        assert isinstance(result, KnowledgeQuery)
        assert result.matched_nodes == []
