class TestGraphStatistics:
    @pytest.mark.asyncio
    async def test_get_statistics(self, service, mock_universe_repo):
        mock_universe_repo.count.side_effect = [10, 5, 20]
        stats = await service.get_graph_statistics()
        assert stats["concept_nodes"] == 10
        assert stats["skill_nodes"] == 5
        assert stats["total_nodes"] == 20

    @pytest.mark.asyncio
    async def test_get_statistics_handles_error(self, service, mock_universe_repo):
        mock_universe_repo.count.side_effect = Exception("DB down")
        stats = await service.get_graph_statistics()
        assert stats["concept_nodes"] == 0
        assert stats["total_nodes"] == 0


class TestConceptToVector:
    def test_returns_768_dim_vector(self, service):
        vector = service._concept_to_vector("test concept")
        assert len(vector) == 768

    def test_deterministic(self, service):
        v1 = service._concept_to_vector("hello")
        v2 = service._concept_to_vector("hello")
        assert v1 == v2

    def test_different_concepts_different_vectors(self, service):
        v1 = service._concept_to_vector("hello")
        v2 = service._concept_to_vector("world")
