"""Tests for hyperparameter search via democratic debate."""

from __future__ import annotations

import math

import pytest

from cohezion.pipeline.hyperparameter_debate import (
    _apply_bounds,
    _clamp,
    _nearest_power_of_2,
)


class TestNearestPowerOf2:
    def test_exact_power(self):
        assert _nearest_power_of_2(128) == 128

    def test_rounds_up(self):
        assert _nearest_power_of_2(100) == 128

    def test_rounds_down(self):
        assert _nearest_power_of_2(70) == 64

    def test_small_value(self):
        assert _nearest_power_of_2(1) == 1

    def test_zero_returns_default(self):
        assert _nearest_power_of_2(0) == 64

    def test_negative_returns_default(self):
        assert _nearest_power_of_2(-5) == 64

    def test_large_value(self):
        assert _nearest_power_of_2(500) == 512


class TestClamp:
    def test_within_range(self):
        assert _clamp(5.0, 0.0, 10.0) == 5.0

    def test_below_min(self):
        assert _clamp(-1.0, 0.0, 10.0) == 0.0

    def test_above_max(self):
        assert _clamp(15.0, 0.0, 10.0) == 10.0

    def test_at_min(self):
        assert _clamp(0.0, 0.0, 10.0) == 0.0

    def test_at_max(self):
        assert _clamp(10.0, 0.0, 10.0) == 10.0


class TestApplyBounds:
    def test_empty_params_returns_defaults(self):
        result = _apply_bounds({})
        assert result["learning_rate"] == 3e-4
        assert result["hidden_dim"] == 128
        assert result["gamma"] == 0.99
        assert result["action_scale"] == 0.01

    def test_clamps_learning_rate(self):
        result = _apply_bounds({"learning_rate": 1.0})
        assert result["learning_rate"] == 1e-2  # Max

    def test_clamps_learning_rate_below_min(self):
        result = _apply_bounds({"learning_rate": 1e-10})
        assert result["learning_rate"] == 1e-5  # Min

    def test_hidden_dim_rounds_to_power_of_2(self):
        result = _apply_bounds({"hidden_dim": 100})
        assert result["hidden_dim"] == 128

    def test_hidden_dim_is_int(self):
        result = _apply_bounds({"hidden_dim": 256.0})
        assert isinstance(result["hidden_dim"], int)

    def test_alias_lr_maps_to_learning_rate(self):
        result = _apply_bounds({"lr": 1e-3})
        assert "learning_rate" in result
        assert result["learning_rate"] == 1e-3

    def test_alias_hidden_maps_to_hidden_dim(self):
        result = _apply_bounds({"hidden": 256})
        assert result["hidden_dim"] == 256

    def test_alias_discount_maps_to_gamma(self):
        result = _apply_bounds({"discount": 0.95})
        assert result["gamma"] == 0.95

    def test_unknown_params_ignored(self):
        result = _apply_bounds({"unknown_param": 42.0})
        assert "unknown_param" not in result
        # Still has defaults
        assert "learning_rate" in result

    def test_gamma_clamped(self):
        result = _apply_bounds({"gamma": 0.5})
        assert result["gamma"] == 0.9  # Min

    def test_kl_weight_accepted(self):
        result = _apply_bounds({"kl_weight": 0.5})
        # kl_weight doesn't have a canonical mapping, so it stays as-is
        # But it's not in defaults, so only if kl_weight is in the spec
        # Check that it doesn't error and defaults are present
        assert "learning_rate" in result

    def test_all_params_provided(self):
        result = _apply_bounds({
            "learning_rate": 1e-3,
            "hidden_dim": 256,
            "gamma": 0.95,
            "action_scale": 0.05,
        })
        assert result["learning_rate"] == 1e-3
        assert result["hidden_dim"] == 256
        assert result["gamma"] == 0.95
        assert result["action_scale"] == 0.05

