# Traces: [FR3, FR26]
"""SubstrateLoom: Named zero-copy shared memory protocol for 12D physics simulation.

Uses /dev/shm for cross-process communication between Python agents and
the Rust physics engine with sub-millisecond state handoff.
"""

from __future__ import annotations

import mmap
import os
import struct
import threading
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Self

import numpy as np


# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

SHM_PATH = "/dev/shm/cohezion_substrate_loom"
F64_BYTES = 8
MAGIC_NUMBER = 0x434F48455A494F4E  # "COHEZION" in hex
HEADER_FORMAT = "<QQQQ"  # magic, sequence, active_buffer, timestamp
HEADER_SIZE = 64


@dataclass(frozen=True, slots=True)
class LoomConfig:
    """Configuration for SubstrateLoom shared memory region."""

    num_agents: int = 10000
    dimensions: int = 12
    pad_to: int = 16  # Pad vector to this many f64s for VLIW-8 alignment (128 bytes)
    shm_path: str = SHM_PATH

    @property
    def padded_vector_bytes(self) -> int:
        return self.pad_to * F64_BYTES

    @property
    def slot_size_bytes(self) -> int:
        return self.num_agents * self.padded_vector_bytes

    @property
    def buffer_size(self) -> int:
        """Aligned header + 2 slots of padded vectors."""
        # 128 byte header (64 used + 64 padding) for slot alignment
        return 128 + 2 * self.slot_size_bytes


class SubstrateLoom:
    """Zero-copy double-buffered shared memory for 12D state vectors.

    Layout:
    [header: 64 bytes] [padding: 64 bytes]
    [slot_0: N agents * 128 bytes]
    [slot_1: N agents * 128 bytes]
    """

    def __init__(self, config: LoomConfig | None = None, create: bool = True) -> None:
        self.config = config or LoomConfig()
        self._shm_file = Path(self.config.shm_path)
        self._mmap: mmap.mmap | None = None
        self._commit_lock = threading.Lock()
        # Pre-allocate padding for zero-copy writes
        self._padding_bytes = b"\x00" * self.config.padded_vector_bytes

        if create:
            self._initialize_shm()
        else:
            self._attach_shm()

    def _initialize_shm(self) -> None:
        """Create and initialize the named SHM segment."""
        if self._shm_file.exists():
            self._shm_file.unlink()

        # Ensure directory exists (though /dev/shm usually does)
        self._shm_file.parent.mkdir(parents=True, exist_ok=True)

        fd = os.open(self._shm_file, os.O_CREAT | os.O_RDWR, 0o600)
        try:
            os.ftruncate(fd, self.config.buffer_size)
            self._mmap = mmap.mmap(fd, self.config.buffer_size, mmap.MAP_SHARED, mmap.PROT_WRITE | mmap.PROT_READ)
            self._mmap[:] = b"\x00" * self.config.buffer_size
            self._write_header(0, 0)
        finally:
            os.close(fd)

    def _attach_shm(self) -> None:
        """Attach to an existing SHM segment."""
        if not self._shm_file.exists():
            msg = f"SHM segment {self._shm_file} does not exist"
            raise FileNotFoundError(msg)

        fd = os.open(self._shm_file, os.O_RDWR)
        try:
            self._mmap = mmap.mmap(fd, 0, mmap.MAP_SHARED, mmap.PROT_WRITE | mmap.PROT_READ)
            magic, _, _, _ = struct.unpack(HEADER_FORMAT, self._mmap[:32])
            if magic != MAGIC_NUMBER:
                msg = f"Invalid magic number in SHM: {magic:#x}"
                raise ValueError(msg)
        finally:
            os.close(fd)

    def _write_header(self, sequence: int, active_slot: int) -> None:
        if self._mmap is None:
            return
        timestamp = time.time_ns()
        header_data = struct.pack(HEADER_FORMAT, MAGIC_NUMBER, sequence, active_slot, timestamp)
        self._mmap[:32] = header_data

    def _read_header(self) -> tuple[int, int, int, int]:
        if self._mmap is None:
            raise RuntimeError("Loom is closed")
        return struct.unpack(HEADER_FORMAT, self._mmap[:32])

    @property
    def active_slot(self) -> int:
        return self._read_header()[2]

    @property
    def sequence_number(self) -> int:
        return self._read_header()[1]

    @property
    def buffer(self) -> mmap.mmap | None:
        return self._mmap

    def write(self, agent_idx: int, vec: np.ndarray) -> None:
        """Write agent data to the INACTIVE slot."""
        if self._mmap is None:
            raise RuntimeError("Loom is closed")

        if not 0 <= agent_idx < self.config.num_agents:
            msg = f"Agent index {agent_idx} out of bounds (0..{self.config.num_agents - 1})"
            raise IndexError(msg)

        inactive = 1 - self.active_slot
        offset = 128 + inactive * self.config.slot_size_bytes + (agent_idx * self.config.padded_vector_bytes)

        # Zero slot then write data (zero-copy attempt)
        self._mmap[offset : offset + self.config.padded_vector_bytes] = self._padding_bytes
        raw_vec = vec.astype(np.float64, copy=False).tobytes()
        self._mmap[offset : offset + len(raw_vec)] = raw_vec

    def commit(self) -> None:
        """Atomic pointer flip."""
        if self._mmap is None:
            raise RuntimeError("Loom is closed")

        with self._commit_lock:
            _, seq, active, _ = self._read_header()
            self._write_header(seq + 1, 1 - active)

    def read(self, agent_idx: int) -> np.ndarray:
        """Read agent data from the ACTIVE slot."""
        if self._mmap is None:
            raise RuntimeError("Loom is closed")

        offset = 128 + self.active_slot * self.config.slot_size_bytes + (agent_idx * self.config.padded_vector_bytes)
        raw = self._mmap[offset : offset + self.config.padded_vector_bytes]
        return np.frombuffer(raw, dtype=np.float64)[: self.config.dimensions].copy()

    def read_all(self) -> np.ndarray:
        """Read all agents from the ACTIVE slot as a single block."""
        if self._mmap is None:
            raise RuntimeError("Loom is closed")

        offset = 128 + self.active_slot * self.config.slot_size_bytes
        raw = self._mmap[offset : offset + self.config.slot_size_bytes]
        data = np.frombuffer(raw, dtype=np.float64)
        # Reshape to (num_agents, padded_dim)
        return data.reshape((self.config.num_agents, self.config.pad_to))

    def write_batch(self, data: np.ndarray) -> None:
        """Write a batch of agent data to the INACTIVE slot."""
        if self._mmap is None:
            raise RuntimeError("Loom is closed")

        inactive = 1 - self.active_slot
        offset = 128 + inactive * self.config.slot_size_bytes

        # Ensure data is padded correctly if it only contains 12D
        if data.shape[1] == self.config.dimensions:
            padded = np.zeros((self.config.num_agents, self.config.pad_to), dtype=np.float64)
            padded[:, : self.config.dimensions] = data
            raw_bytes = padded.tobytes()
        else:
            raw_bytes = data.astype(np.float64, copy=False).tobytes()

        self._mmap[offset : offset + len(raw_bytes)] = raw_bytes

    def close(self) -> None:
        if self._mmap is not None:
            self._mmap.close()
            self._mmap = None

    def unlink(self) -> None:
        self.close()
        if self._shm_file.exists():
            self._shm_file.unlink()

    def __enter__(self) -> Self:
        return self

    def __exit__(self, *_: object) -> None:
        self.close()
